events = ["click", "key_press", "click", "close"]   # user ke kaam, bari bari

def on_click():
    print("Button dabaya gaya: label ka text badla")

def on_key_press():
    print("Key dabayi gayi: entry mein harf aaya")

# har event ka jura hua function (jaise command=on_click)
handlers = {"click": on_click, "key_press": on_key_press}

print("Program idle hai, event ka intezar...")
for event in events:
    if event == "close":
        print("Window band: program khatam")
        break
    handlers[event]()   # event se jura function chalao
